(function(root){
const colors=['#eaa0a0','#8db9e6','#d9b667','#b4a0d8'];
function axis(n){return Math.abs(n||0)<.18?0:Math.sign(n)*(Math.abs(n)-.18)/.82;}
function stick(x,y){x=Number.isFinite(x)?Math.max(-1,Math.min(1,x)):0;y=Number.isFinite(y)?Math.max(-1,Math.min(1,y)):0;const length=Math.hypot(x,y);if(length<=.18)return{x:0,y:0};const strength=(Math.min(length,1)-.18)/.82;return{x:x/length*strength,y:y/length*strength};}
function input(p){let {x,y}=stick(p.axes?.[0],p.axes?.[1]);const b=i=>!!p.buttons?.[i]?.pressed;const dx=(b(15)?1:0)-(b(14)?1:0),dy=(b(13)?1:0)-(b(12)?1:0);if(dx||dy){const length=Math.hypot(dx,dy);x=dx/length;y=dy/length;}return{x,y,jump:b(0),baa:b(2),bite:b(1),hat:b(3)};}
function turn(current,target,dt){const delta=Math.atan2(Math.sin(target-current),Math.cos(target-current));return current+delta*(1-Math.exp(-18*dt));}
function sheep(id,n){return{id,n,x:480+n*90,y:350,z:0,vz:0,face:1,heading:0,walk:0,hat:0,baa:0,cool:0,bite:0,biteCool:0,attack:false,health:3,ko:0,prev:{},connected:true,color:colors[n%4]};}
function step(s,i,dt){dt=Math.min(Math.max(dt,0),.05);s.attack=false;if(s.ko>0){s.ko=Math.max(0,s.ko-dt);s.prev={...i};if(s.ko===0){s.health=3;s.x=480+s.n*90;s.y=350;s.z=0;s.vz=0;s.bite=0;s.biteCool=.5;}return;}const priorBite=s.bite;s.bite=Math.max(0,s.bite-dt);if(priorBite>.25&&s.bite<=.25)s.attack=true;s.biteCool=Math.max(0,s.biteCool-dt);if(i.bite&&!s.prev.bite&&s.biteCool===0){s.bite=.45;s.biteCool=.8;}s.x=Math.max(110,Math.min(1090,s.x+i.x*210*dt));s.y=Math.max(170,Math.min(660,s.y+i.y*210*dt));if(Math.hypot(i.x,i.y)>.001)s.heading=turn(s.heading,Math.atan2(i.y,i.x),dt);if(i.x)s.face=i.x<0?-1:1;s.walk+=Math.hypot(i.x,i.y)*dt*14;if(i.jump&&!s.prev.jump&&s.z===0)s.vz=410;if(i.hat&&!s.prev.hat)s.hat=(s.hat+1)%4;if(i.baa&&!s.prev.baa&&s.cool<=0){s.baa=1.1;s.cool=.5;}s.vz-=1000*dt;s.z+=s.vz*dt;if(s.z<0){s.z=0;s.vz=0;}s.baa=Math.max(0,s.baa-dt);s.cool=Math.max(0,s.cool-dt);s.prev={...i};}
function combat(sheep){const hits=[];for(const a of sheep){if(!a.attack||a.ko>0)continue;for(const b of sheep){if(a===b||b.ko>0)continue;const dx=b.x-a.x,dy=b.y-a.y;if(Math.hypot(dx,dy)<=83&&dx*Math.cos(a.heading)+dy*Math.sin(a.heading)>=Math.hypot(dx,dy)*.5&&Math.abs(a.z-b.z)<55)hits.push(b);}}for(const b of hits){if(b.ko>0)continue;b.health=Math.max(0,b.health-1);if(b.health===0){b.ko=5;b.baa=0;b.bite=0;b.z=0;b.vz=0;}}for(const a of sheep)a.attack=false;return hits.length;}
root.Meadow={axis,stick,turn,input,sheep,step,combat};if(typeof module!=='undefined')module.exports=root.Meadow;
})(typeof window==='undefined'?globalThis:window);
